<?php
namespace App\services;
use App\config\Database;
use RuntimeException;
final class CreditService {
    public function reserve(int $userId,int $amount,string $description,string $referenceType='agent_run',?string $referenceId=null):int{$pdo=Database::get();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT balance FROM user_credits WHERE user_id=? FOR UPDATE');$s->execute([$userId]);$row=$s->fetch();if(!$row)throw new RuntimeException('Carteira de créditos não encontrada.');$balance=(int)$row['balance'];if($balance<$amount)throw new RuntimeException('Créditos insuficientes. Faça upgrade do plano para continuar.');$new=$balance-$amount;$pdo->prepare('UPDATE user_credits SET balance=?,updated_at=NOW() WHERE user_id=?')->execute([$new,$userId]);$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'debit',?,?,?,?,?,'reserved',NOW())")->execute([$userId,$amount,$new,$description,$referenceType,$referenceId]);$id=(int)$pdo->lastInsertId();$pdo->commit();return $id;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    public function confirm(int $txId,?string $referenceId=null):void{$sql="UPDATE credit_transactions SET status='confirmed'";$args=[];if($referenceId!==null){$sql.=',reference_id=?';$args[]=$referenceId;}$sql.=" WHERE id=? AND status='reserved'";$args[]=$txId;Database::get()->prepare($sql)->execute($args);}
    public function refund(int $txId):void{$pdo=Database::get();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT * FROM credit_transactions WHERE id=? FOR UPDATE");$s->execute([$txId]);$t=$s->fetch();if(!$t||$t['status']!=='reserved'){$pdo->commit();return;}$b=$pdo->prepare('SELECT balance FROM user_credits WHERE user_id=? FOR UPDATE');$b->execute([$t['user_id']]);$new=(int)$b->fetchColumn()+(int)$t['amount'];$pdo->prepare('UPDATE user_credits SET balance=?,updated_at=NOW() WHERE user_id=?')->execute([$new,$t['user_id']]);$pdo->prepare("UPDATE credit_transactions SET status='refunded' WHERE id=?")->execute([$txId]);$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'refund',?,?,'Reembolso automático após falha',?,?, 'confirmed',NOW())")->execute([$t['user_id'],$t['amount'],$new,$t['reference_type'],$t['reference_id']]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    public function grant(int $userId,int $amount,string $description,string $referenceType,?string $referenceId=null):void{$pdo=Database::get();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT balance FROM user_credits WHERE user_id=? FOR UPDATE');$s->execute([$userId]);$new=(int)$s->fetchColumn()+$amount;$pdo->prepare('UPDATE user_credits SET balance=?,updated_at=NOW() WHERE user_id=?')->execute([$new,$userId]);$pdo->prepare("INSERT INTO credit_transactions(user_id,type,amount,balance_after,description,reference_type,reference_id,status,created_at) VALUES(?,'credit',?,?,?,?,?,'confirmed',NOW())")->execute([$userId,$amount,$new,$description,$referenceType,$referenceId]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}
